"""Read the verified results generated by preprocessing.py."""
from pathlib import Path
import argparse
import json


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--results', type=Path,
                        default=Path(__file__).resolve().parent / 'results')
    args = parser.parse_args()
    path = args.results / 'analysis_summary.json'
    if not path.exists():
        parser.error('Run preprocessing.py first; analysis_summary.json is missing.')
    data = json.loads(path.read_text(encoding='utf-8'))
    print('WEEK 2 VERIFIED LOGISTICS SUMMARY')
    for key, value in data.items():
        if key != 'shipping_modes_non_canceled':
            print(f'{key}: {value:,.4f}' if isinstance(value, float)
                  else f'{key}: {value:,}')
    print('\nShipping modes (unique non-canceled orders):')
    for row in data['shipping_modes_non_canceled']:
        print(f"{row['Shipping Mode']}: {row['orders']:,} orders, "
              f"{row['late_rate']:.2%} late")


if __name__ == '__main__':
    main()
